var CC_TYPES = {feat:'Features', fix:'Bug Fixes', perf:'Performance', docs:'Documentation', style:'Styles', refactor:'Refactoring', test:'Tests', build:'Build', ci:'CI', chore:'Chores', revert:'Reverts'};
function ccParseLine(line){
  line=line.trim();
  if(!line) return null;
  var m=/^(\w+)(\(([^)]*)\))?(!)?\s*:\s*(.*)$/.exec(line);
  if(!m) return null;
  return {type:m[1].toLowerCase(), scope:m[3]||null, breaking:!!m[4], subject:m[5].trim()};
}
function ccBump(commits){
  var hasBreaking=false, hasFeat=false, hasFix=false;
  for(var i=0;i<commits.length;i++){
    if(commits[i].breaking) hasBreaking=true;
    if(commits[i].type==='feat') hasFeat=true;
    if(commits[i].type==='fix') hasFix=true;
  }
  if(hasBreaking) return 'major';
  if(hasFeat) return 'minor';
  if(hasFix) return 'patch';
  return 'none';
}
function ccNextVersion(ver, bump){
  var m=/^v?(\d+)\.(\d+)\.(\d+)/.exec(ver.trim());
  if(!m) return null;
  var major=+m[1], minor=+m[2], patch=+m[3];
  if(bump==='major') return (major+1)+'.0.0';
  if(bump==='minor') return major+'.'+(minor+1)+'.0';
  if(bump==='patch') return major+'.'+minor+'.'+(patch+1);
  return ver;
}
function ccGroup(commits){
  var g={};
  for(var i=0;i<commits.length;i++){ var c=commits[i]; (g[c.type]||(g[c.type]=[])).push(c); }
  return g;
}
function ccParse(text){
  var lines=String(text).split(/\r?\n/);
  var out=[];
  for(var i=0;i<lines.length;i++){
    if(/BREAKING CHANGE:/.test(lines[i]) && out.length) out[out.length-1].breaking=true;
    var c=ccParseLine(lines[i]);
    if(c) out.push(c);
  }
  return out;
}
function ccChangelog(text, opts){
  opts=opts||{};
  var commits=ccParse(text);
  var groups=ccGroup(commits);
  var order=['feat','fix','perf','refactor','docs','style','test','build','ci','chore','revert'];
  var lines=[];
  var title = opts.version ? ('## '+opts.version) : '## Changes';
  if(opts.date) title += ' ('+opts.date+')';
  lines.push(title); lines.push('');
  var any=false;
  for(var i=0;i<order.length;i++){
    var t=order[i];
    if(groups[t]){
      any=true;
      lines.push('### '+(CC_TYPES[t]||t));
      for(var j=0;j<groups[t].length;j++){
        var c=groups[t][j];
        lines.push('- '+(c.scope?('**'+c.scope+'**: '):'')+c.subject+(c.breaking?' (BREAKING)':''));
      }
      lines.push('');
    }
  }
  if(!any) lines.push('_无变更_');
  return lines.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parse:ccParse, parseLine:ccParseLine, bump:ccBump, nextVersion:ccNextVersion, group:ccGroup, changelog:ccChangelog };
}
if (typeof window !== 'undefined') {
  window.ChangelogForgePure = { parse:ccParse, bump:ccBump, nextVersion:ccNextVersion, changelog:ccChangelog };
}
